intro:
Formats args according to the format string fmt with appended '\n' (which means that each output ends with a new-line), and inserts the result into os stream.

1) Equivalent to:
std::print(os, "{}\n", std::format(os.getloc(), fmt, args...));

2) Equivalent to: 
std::print(os, "\n");

The behavior is undefined if std::formatter<Ti, char> does not meet the BasicFormatter requirements for any Ti in Args (as required by std::make_format_args).

examples.code:
#include <print>
#include <cstdio>
#include <format>
#include <fstream>
#include <cassert>
#include <type_traits>
#include <utility>
#include <sstream>
int main() {
    std::FILE *file = std::tmpfile();
    assert(file);
    int number = 7;
    std::vprint_unicode(file, "{}", std::make_format_args(number));
    std::vprint_nonunicode(file, "{}", std::make_format_args(number));
    std::rewind(file);
    assert(std::fgetc(file) == '7');
    assert(std::fgetc(file) == '7');
    std::fclose(file);
    std::ostringstream stream;
    std::vprint_unicode(stream, "{}", std::make_format_args(number));
    std::vprint_nonunicode(stream, "{}", std::make_format_args(number));
    std::println(stream, "{}", number);
    assert(stream.str() == "777\n");
}
